import json
from pathlib import Path

from mock_api import TRACE, search
from query_audit import build_rejection
from timezone_defaults import DEFAULT_TIMEZONE, MISSING_TZ_POLICY
from window_projection import parse_bound


def validate_range(payload):
    errors = []
    values = {}

    for param in ("start_date", "end_date"):
        if param not in payload:
            if param == "start_date":
                errors.append(build_rejection(param, "is required", payload))
            continue
        try:
            values[param] = parse_bound(payload[param])
        except (TypeError, ValueError, OverflowError) as exc:
            errors.append(build_rejection(param, f"invalid ISO 8601 datetime: {exc}", payload))

    if "start_date" not in values or "end_date" not in values:
        return errors

    start = values["start_date"]
    end = values["end_date"]
    start_utc = start.astimezone(DEFAULT_TIMEZONE)
    end_utc = end.astimezone(DEFAULT_TIMEZONE)
    normalized = {
        "start_utc": start_utc.isoformat(),
        "end_utc": end_utc.isoformat(),
        "missing_timezone_policy": MISSING_TZ_POLICY,
        "default_timezone": "UTC",
    }

    if start_utc > end_utc:
        errors.append(
            build_rejection(
                "date_range",
                "start must be before or equal to end after UTC normalization",
                payload,
                normalized,
            )
        )

    start_local = start.replace(tzinfo=None)
    end_local = end.replace(tzinfo=None)
    same_local_date = start_local.date() == end_local.date()
    same_repeated_hour = start_local.hour == end_local.hour
    different_offsets = start.utcoffset() != end.utcoffset()
    if same_local_date and same_repeated_hour and different_offsets and end_local < start_local:
        errors.append(
            build_rejection(
                "date_range",
                "ambiguous fall-back DST range has an earlier local end clock",
                payload,
                normalized,
            )
        )

    return errors


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

